-- Homepage: Custom Size + Alterations section, placed after the first sections
INSERT INTO homepage_sections (section_type, admin_label, settings, sort_order, status) SELECT 'services', 'Services — Custom Size & Alterations', '{\"eyebrow\":\"Tailored For You\",\"title\":\"Your Size. Your Style.\",\"subtitle\":\"Two services that make Urban Collections different.\",\"card1_image\":\"https://images.unsplash.com/photo-1593030761757-71fae45fa0e7?auto=format&fit=crop&w=1400&q=80\",\"card1_eyebrow\":\"Custom Size Studio\",\"card1_title\":\"Ready-made, made to your measurements\",\"card1_text\":\"Design your shalwar qameez, kurta, office shirt or ladies suit on our interactive mannequin — at the ready-made price.\",\"card1_points\":\"Pick colour, collar, cuffs, daman & shalwar style\\nStart from S–XXL or our height & weight size finder\\nStep-by-step guide to measure yourself\",\"card1_button_text\":\"Customise your size\",\"card1_button_url\":\"custom-size\",\"card2_image\":\"https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?auto=format&fit=crop&w=1400&q=80\",\"card2_eyebrow\":\"Alteration Service\",\"card2_title\":\"Perfect fit for every outfit\",\"card2_text\":\"Coat pant fitting, sherwani and prince coat, bridal and party wear — bought from us or anywhere else.\",\"card2_points\":\"See estimated price & time before you send it\\nDrop off at our store or courier pickup\\nTrack your request online\",\"card2_button_text\":\"Request an alteration\",\"card2_button_url\":\"alterations\",\"bg_color\":\"#F7F6F2\"}', 25, 'published' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM homepage_sections WHERE section_type = 'services');

